function Accordion({icon,title,body,open,press,children}:{icon:keyof typeof Ionicons.glyphMap;title:string;body:string;open:boolean;press:()=>void;children:React.ReactNode}){const{palette}=useAppTheme();return <View style={{borderBottomColor:palette.border,borderBottomWidth:1}}><Pressable accessibilityRole="button" accessibilityState={{expanded:open}} onPress={press} style={s.accordionHead}><View style={[s.icon,{backgroundColor:palette.successSoft}]}><Ionicons name={icon} size={20} color={palette.success}/></View><View style={{flex:1,minWidth:0}}><Text style={[s.rowTitle,{color:palette.text}]}>{title}</Text><Muted>{body}</Muted></View><Ionicons name={open?'chevron-up':'chevron-down'} size={20} color={palette.muted}/></Pressable>{open?<View style={[s.accordionBody,{backgroundColor:palette.background,borderTopColor:palette.border}]}>{children}</View>:null}</View>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:1380,alignSelf:'center',paddingBottom:28},heading:{marginBottom:14},title:{fontSize:24,fontWeight:'900',marginBottom:5},layout:{flexDirection:'row',alignItems:'flex-start',gap:16},stack:{flexDirection:'column'},menu:{width:245,padding:12},menuTitle:{fontWeight:'900',margin:8},menuRow:{minHeight:48,borderRadius:10,flexDirection:'row',alignItems:'center',gap:10,paddingHorizontal:11},main:{flex:1,width:'100%',minWidth:0,gap:14},two:{flexDirection:'row',gap:14},flex:{flex:1,minWidth:0},sectionTitle:{fontSize:19,fontWeight:'900',marginBottom:4},sectionHead:{flexDirection:'row',justifyContent:'space-between',alignItems:'flex-start',gap:12},overviewTop:{flexDirection:'row',alignItems:'center',gap:12},ring:{width:112,height:112,borderRadius:56,borderWidth:10,alignItems:'center',justifyContent:'center',flexShrink:0},used:{fontSize:23,fontWeight:'900'},storageList:{flex:1,minWidth:0},storageRow:{minHeight:38,flexDirection:'row',alignItems:'center',gap:7},upgrade:{width:'100%',borderRadius:14,padding:12,marginTop:14,flexDirection:'row',alignItems:'center',gap:10},upgradeCopy:{flex:1,minWidth:0},clearButton:{minHeight:42,borderWidth:1,borderRadius:10,paddingHorizontal:10,alignItems:'center',justifyContent:'center'},mobileOptions:{padding:0,overflow:'hidden'},accordionHead:{minHeight:76,paddingHorizontal:14,flexDirection:'row',alignItems:'center',gap:11},accordionBody:{paddingHorizontal:14,paddingBottom:10,borderTopWidth:1},toggle:{minHeight:70,borderBottomWidth:1,flexDirection:'row',alignItems:'center',gap:11},cycle:{minHeight:60,borderBottomWidth:1,flexDirection:'row',alignItems:'center',gap:10},action:{minHeight:67,borderBottomWidth:1,flexDirection:'row',alignItems:'center',gap:11},icon:{width:40,height:40,borderRadius:12,alignItems:'center',justifyContent:'center',flexShrink:0},rowTitle:{fontWeight:'900',marginBottom:2},saving:{textAlign:'center',marginVertical:8},detail:{width:'100%',maxWidth:720,alignSelf:'center'},back:{minHeight:54,flexDirection:'row',alignItems:'center',gap:8},detailTitle:{fontSize:23,fontWeight:'900'}});
